// Altbestand gespeicherter Vorlagen: bekannter Tippfehler früherer Standardtexte
export const fixLegacyTemplateTypos = (html) => (typeof html === 'string' && html.includes('Die Miete is nach')
    ? html.split('Die Miete is nach').join('Die Miete ist nach')
    : html);
